// Category resolver (plan item #4): some titles were parked in the default
// "action" bucket although they are clearly horror / anime / drama. The
// corrections live in src/data/category-overrides.js (auto-generated by
// scripts/rebalance-categories.mjs) so movies.js itself stays untouched.
import { CATEGORY_OVERRIDES } from '../data/category-overrides.js';

export function categoryOf(m) {
    return CATEGORY_OVERRIDES[m.id] || m.category;
}

// Returns the entry with the corrected category when it differs.
export function withCategory(m) {
    const c = categoryOf(m);
    return c === m.category ? m : { ...m, category: c };
}
